begin;
create or replace function public.mir_supplier_po_detail(p_po uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,mir_core as $$declare org uuid;out jsonb;begin select organization_id into org from mir_core.account_settings where singleton;if not mir_core.coordination_allowed(org) then raise exception 'Coordination requise' using errcode='42501';end if;
 select to_jsonb(o)||jsonb_build_object('snapshot',r.snapshot,'supplier',to_jsonb(s),'lines',(select coalesce(jsonb_agg(to_jsonb(l)),'[]') from mir_core.order_lines l where l.organization_id=org and l.order_id=o.id and l.revision=o.revision),'documents',(select coalesce(jsonb_agg(to_jsonb(d)),'[]') from mir_core.documents d where d.organization_id=org and d.order_id=o.id),'sendJobs',(select coalesce(jsonb_agg(jsonb_build_object('id',j.id,'revision',j.revision,'status',j.status,'messageId',j.provider_message_id,'error',j.last_error)),'[]') from mir_core.send_jobs j where j.organization_id=org and j.order_id=o.id),'receivedQty',coalesce((select sum(cr.received_qty) from mir_core.coordination_routes cr where cr.organization_id=org and cr.supplier_order_id=o.id),0),'expectedDate',(select min(cr.expected_date) from mir_core.coordination_routes cr where cr.organization_id=org and cr.supplier_order_id=o.id),'expectedQty',coalesce((select sum(cr.quantity) from mir_core.coordination_routes cr where cr.organization_id=org and cr.supplier_order_id=o.id),0)) into out from mir_core.orders o join mir_core.order_revisions r on(r.organization_id,r.order_id,r.revision)=(o.organization_id,o.id,o.revision) join mir_core.suppliers s on(s.organization_id,s.id)=(o.organization_id,o.supplier_id) where o.organization_id=org and o.id=p_po and o.kind='supplier';if out is null then raise exception 'Bon introuvable' using errcode='42501';end if;return out;
end$$;

commit;
